from pathlib import Path

p=Path('code')
s=p.read_text(encoding='utf-8')
MARK='MAXESS RESULTS EXPERIENCE RUTHLESS RESET'
if MARK in s:
    print('Ruthless reset already present')
    raise SystemExit(0)

