s=s.replace('</style>',CSS+'\n</style>',1)

JS=r'''
(function(){
 const root=document.getElementById('resultsView'); if(!root) return;
 const mount=()=>{
  if(!root.classList.contains('visible') || root.dataset.rrRuthless==='1') return;
  const hero=root.querySelector('.result-hero'); if(!hero) return;
  const score=Math.round(Number(document.getElementById('overallScore')?.textContent||0));
  const dims=[...root.querySelectorAll('#dimensionConstellation .dimension-orb')].map((el,i)=>({name:el.querySelector('.dimension-name')?.textContent?.trim()||['Direction','Communication','Evaluation','Iteration','Systems Thinking'][i]||'Dimension',score:Number(el.querySelector('.dimension-score')?.textContent||0)}));
  dims.sort((a,b)=>b.score-a.score); const hi=dims[0]||{name:'Direction',score:score}; const lo=dims[dims.length-1]||hi;
  const radar=root.querySelector('#dimensionConstellation')?.innerHTML||'';
  [...root.children].forEach(ch=>{ if(ch!==hero) ch.style.display='none'; });
  const out=document.createElement('section'); out.className='maxess-ruthless';
  out.innerHTML=`
   <div class="rr-opening"><div><div class="rr-kicker">WHAT YOUR SCORE TELLS THE STORY</div><div class="quote">You already have a real advantage in <em>${escapeHTML(hi.name)}</em>. Your next leap is becoming more deliberate about <em>${escapeHTML(lo.name).toLowerCase()}</em>.</div></div><div class="rr-score"><strong>${score}/100</strong><span>MAXESS capability snapshot</span></div></div>
   <section class="rr-section rr-fingerprint"><div class="rr-kicker">YOUR AI FINGERPRINT</div><h3>The shape underneath your score.</h3><p>Five capabilities. One recognizable pattern. The goal isn't a perfect shape — it's a stronger one.</p><div class="rr-radar">${radar}</div><div class="rr-read"><div><span>Natural advantage</span><strong>${escapeHTML(hi.name)}</strong><p>${hi.score}/100 · the capability you can already lean on.</p></div><div><span>Highest leverage</span><strong>${escapeHTML(lo.name)}</strong><p>${lo.score}/100 · the clearest opportunity for deliberate growth.</p></div><div><span>What matters next</span><strong>Better judgment</strong><p>Keep what works. Spot what doesn't. Tell AI exactly how to improve it.</p></div></div></section>
   <section class="rr-section rr-system"><div class="rr-kicker">HOW YOU WORK WITH AI</div><h2 class="rr-h">AI is the engine.<br><span style="color:#b895ff">You are the director.</span></h2><p class="rr-copy" style="margin-left:auto;margin-right:auto">Know what you want. Give the context. Ask clearly. Look closely. Score the result. Improve it. Repeat.</p><div class="rr-seq">${['KNOW','TELL','ASK','LOOK','SCORE','IMPROVE','REPEAT'].map(x=>`<span>${x}</span>`).join('')}</div></section>
   <section class="rr-section rr-naya"><div class="rr-orb">N</div><div><div class="rr-kicker">NAYA · PERSONAL GUIDE</div><h3>“Okay. Now we know where to look.”</h3><blockquote>Your result isn't a verdict. It's a starting point. Keep the capability that's already working. Practice the one that creates the most leverage. Then use that combination to make something real.</blockquote><small>Naya is here to interpret the pattern — not overwhelm you with more information.</small></div></section>
   <section class="rr-section rr-masters"><div class="rr-masters-head"><div><div class="rr-kicker">NAYA · MASTER INTELLIGENCE</div><h3>Specific work deserves specific mastery.</h3></div><p>One visual introduction to the kinds of specialized intelligence Naya can bring to the work in front of you.</p></div><div class="rr-stage"><article class="rr-main-master"><div class="rr-gem">✦</div><h4>Naya Master ${escapeHTML(hi.name)}</h4><span>Your natural advantage</span><p>Start where you're already strong. Use this capability as the foundation for the next thing you build.</p></article><div class="rr-side-wrap"><article class="rr-side-master"><div class="rr-gem">◆</div><div class="rr-side-copy"><h5>Naya Master ${escapeHTML(lo.name)}</h5><span>Your leverage opportunity</span><p>Practice the capability with the clearest upside.</p></div></article><article class="rr-side-master"><div class="rr-gem">△</div><div class="rr-side-copy"><h5>Naya Master Strategist</h5><span>Turn intent into action</span><p>Bring direction, priorities, and decisions into the work.</p></div></article></div></div></section>
   <section class="rr-final"><div class="rr-kicker">YOUR NEXT CHAPTER</div><h2 class="rr-h">Now make the capability real.</h2><p>You know more about where you are and where the leverage is. The next step is to use it — in work, learning, creation, or something that matters to you.</p><div class="rr-actions"><button class="rr-primary" data-rr-go type="button">MASTER AI</button><button class="rr-secondary" data-rr-save type="button">SAVE MY RESULTS</button></div><div class="rr-note">Your MAXESS result is a capability snapshot based on your assessment responses. It is not a diagnosis, prediction, or guarantee.</div></section>`;
  root.appendChild(out); root.dataset.rrRuthless='1';
  out.querySelector('[data-rr-go]')?.addEventListener('click',()=>document.getElementById('freeTrialButton')?.click());
  out.querySelector('[data-rr-save]')?.addEventListener('click',()=>document.getElementById('pdfButton')?.click());
 };
 new MutationObserver(mount).observe(root,{attributes:true,attributeFilter:['class']}); mount();
})();
'''

s=s.replace('</script>',JS+'\n</script>',1)
p.write_text(s,encoding='utf-8')
print('Ruthless Results reset applied')
